async def act(page):
    """Search for the post '40 of our most helpful AI tips from 2025' using the site search helper
    and, if found, navigate to it and leave the comment 'Great article!'.

    This function uses the site-aware KB helper create_curated_collection_by_search(...) to
    drive the visible search widget (the helper itself performs await page.goto('/')).
    After locating a candidate post it navigates to the post URL, finds a comment textbox
    (role="textbox"), fills the comment text, optionally fills name/email fields, and
    attempts to submit using a button scoped to the main region.
    """

    # 1) Use the site-aware search helper to find the post. Try several keyword variants.
    keywords = [
        "40 of our most helpful AI tips from 2025",
        "40 of our most helpful AI tips",
        "AI tips 2025",
        "helpful AI tips 2025",
        "AI tips",
    ]

    results = []
    for kw in keywords:
        try:
            # This KB helper navigates to '/' itself and uses accessibility-role selectors
            results = await create_curated_collection_by_search(page, kw, max_results=0, resolve_links=True)
        except Exception:
            results = []
        if results:
            break

    if not results:
        # Could not find relevant posts via the visible search widget.
        return

    # 2) Choose the best matching result by title heuristics
    target_item = None
    full_target = "40 of our most helpful ai tips from 2025"
    for item in results:
        if not isinstance(item, dict):
            continue
        title = (item.get("title") or "").strip()
        if title and full_target in title.lower():
            target_item = item
            break

    if not target_item:
        # fallback: find a title containing both 'ai' and 'tip'
        for item in results:
            if not isinstance(item, dict):
                continue
            title = (item.get("title") or "").lower()
            if "ai" in title and "tip" in title:
                target_item = item
                break

    if not target_item:
        # final fallback: first result
        if isinstance(results[0], dict):
            target_item = results[0]
        else:
            return

    post_url = target_item.get("url") if isinstance(target_item, dict) else None
    if not post_url:
        return

    # 3) Navigate to the post page. Use goto so subsequent selectors are predictable.
    await page.goto(post_url)
    try:
        await page.wait_for_load_state("networkidle")
    except Exception:
        # continue even if networkidle times out
        pass

    # 4) Find the comment textbox (role="textbox") using accessibility-role-centric selectors.
    all_textboxes = page.get_by_role("textbox")
    try:
        tb_count = await all_textboxes.count()
    except Exception:
        tb_count = 0

    comment_locator = None

    # Prefer a textbox whose accessible attributes mention comment/reply/message
    for i in range(tb_count):
        tb = all_textboxes.nth(i)
        try:
            attrs = await tb.evaluate(
                "el => (el.getAttribute('aria-label') || el.getAttribute('placeholder') || el.getAttribute('name') || el.getAttribute('id') || '')"
            )
        except Exception:
            attrs = ""
        if attrs and any(k in attrs.lower() for k in ("comment", "leave a comment", "your comment", "reply", "message")):
            comment_locator = tb
            break

    # If not found, prefer a textarea element
    if comment_locator is None:
        for i in range(tb_count):
            tb = all_textboxes.nth(i)
            try:
                tag = await tb.evaluate("el => (el.tagName || '').toLowerCase()")
            except Exception:
                tag = ""
            if tag == "textarea":
                comment_locator = tb
                break

    # If still not found and there's exactly one textbox, assume it is the comment box
    if comment_locator is None and tb_count == 1:
        comment_locator = all_textboxes.nth(0)

    # Additional fallback: look for a textbox inside main
    if comment_locator is None:
        try:
            main = page.get_by_role("main")
            main_textboxes = main.get_by_role("textbox")
            main_tb_count = await main_textboxes.count()
        except Exception:
            main_tb_count = 0
            main_textboxes = None
        if main_tb_count > 0 and main_textboxes is not None:
            comment_locator = main_textboxes.nth(0)

    if comment_locator is None:
        # No comment input found; cannot proceed
        return

    # 5) Fill the comment text
    try:
        await comment_locator.fill("Great article!")
    except Exception:
        try:
            await comment_locator.focus()
            await comment_locator.type("Great article!")
        except Exception:
            return

    # 6) Optionally fill name/email fields (best-effort). Skip the comment locator itself.
    try:
        total_textboxes = await all_textboxes.count()
    except Exception:
        total_textboxes = 0

    try:
        comment_eh = await comment_locator.element_handle()
    except Exception:
        comment_eh = None

    for i in range(total_textboxes):
        tb = all_textboxes.nth(i)
        try:
            eh = await tb.element_handle()
        except Exception:
            eh = None
        try:
            is_same = False
            if comment_eh is not None and eh is not None:
                is_same = await page.evaluate("(a,b) => a === b", comment_eh, eh)
        except Exception:
            is_same = False
        if is_same:
            continue
        try:
            tb_attrs = await tb.evaluate(
                "el => (el.getAttribute('aria-label') || el.getAttribute('placeholder') || el.getAttribute('name') || el.getAttribute('id') || '')"
            )
        except Exception:
            tb_attrs = ""
        if not tb_attrs:
            continue
        low = tb_attrs.lower()
        try:
            if "email" in low:
                await tb.fill("test@example.com")
            elif "name" in low and ("first" not in low and "last" not in low):
                await tb.fill("Test User")
        except Exception:
            # ignore optional fill failures
            pass

    # 7) Submit the comment: prefer a button scoped to the main region
    submit_keywords = ("post", "submit", "comment", "send", "leave a comment", "add comment", "post comment")
    try:
        main = page.get_by_role("main")
        buttons_in_main = main.get_by_role("button")
        btn_count = await buttons_in_main.count()
    except Exception:
        buttons_in_main = page.get_by_role("button")
        try:
            btn_count = await buttons_in_main.count()
        except Exception:
            btn_count = 0

    for i in range(btn_count):
        b = buttons_in_main.nth(i)
        try:
            txt = (await b.inner_text() or "").lower()
        except Exception:
            txt = ""
        if any(k in txt for k in submit_keywords):
            try:
                await b.click()
                return
            except Exception:
                # try next candidate
                pass

    # Fallback: try global buttons
    global_buttons = page.get_by_role("button")
    try:
        global_btn_count = await global_buttons.count()
    except Exception:
        global_btn_count = 0

    for i in range(global_btn_count):
        b = global_buttons.nth(i)
        try:
            txt = (await b.inner_text() or "").lower()
        except Exception:
            txt = ""
        if any(k in txt for k in submit_keywords):
            try:
                await b.click()
                return
            except Exception:
                pass

    # Last resort: try common submit keystrokes while focused in the comment box
    try:
        await comment_locator.press("Control+Enter")
    except Exception:
        try:
            await comment_locator.press("Enter")
        except Exception:
            pass

    return

